(3) 删除子串操作
int Delete(String *S, int pos, int len)
{ int i;
   if(S->length <= 0)
   {      printf(" 数组中未存放字符无元素可删 ! \n");
   return 0;     }
   else if(pos < 0 || len < 0 || pos+len > S->length)
   {      printf(" 参数 pos 和 len 出错 ");             return 0;        }
   else{
   for(i = pos+len; i <= S->length-1; i++)
   S->str[i-len] = S->str[i]; S->length -= len; return 1;           }
}



